const fs=require('node:fs'),path=require('node:path');
const data=JSON.parse(fs.readFileSync('content/articles.json','utf8'));
const config=JSON.parse(fs.readFileSync('site.json','utf8'));
if(!Array.isArray(data))throw Error('articles.json doit être une liste.');
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const slugs=new Set();
for(const article of data){if(!/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(article.slug)||slugs.has(article.slug)||typeof article.title!=='string'||!article.title.trim()||typeof article.content!=='string')throw Error('Chaque article doit avoir un slug unique, un titre et un contenu texte.');slugs.add(article.slug);}
const published=data.filter(article=>article.published===true);
const page=(title,body)=>`<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(title)} · ${esc(config.name)}</title><meta name="description" content="${esc(config.description)}"><link rel="stylesheet" href="/style.css"></head><body><header><a href="/">${esc(config.name)}</a><span>Journal indépendant</span></header><main>${body}</main><footer>${esc(config.name)} · Tous les articles sont rédigés par leur auteur.</footer><script src="/search.js" defer></script></body></html>`;
fs.rmSync('dist',{recursive:true,force:true});fs.mkdirSync('dist/articles',{recursive:true});
const cards=published.map(a=>`<article data-search="${esc([a.title,a.summary,a.category].join(' ').toLowerCase())}" data-category="${esc(a.category||'Général')}"><p class="category">${esc(a.category||'Général')}</p><h2><a href="/articles/${a.slug}/">${esc(a.title)}</a></h2><p>${esc(a.summary||'')}</p><p class="byline">${esc(a.author||'')}</p></article>`).join('');
const categories=[...new Set(published.map(a=>a.category||'Général'))];
fs.writeFileSync('dist/index.html',page('Accueil',`<section class="intro"><p class="category">Le journal</p><h1>${esc(config.name)}</h1><p>${esc(config.description)}</p></section><div class="filters"><label>Rechercher<input id="search" type="search" placeholder="Titre, sujet…"></label><label>Catégorie<select id="category"><option value="">Toutes</option>${categories.map(c=>`<option>${esc(c)}</option>`).join('')}</select></label></div><div class="articles">${cards}</div><p id="empty" ${published.length?'hidden':''}>${published.length?'Aucun article ne correspond à votre recherche.':'Aucun article publié pour le moment.'}</p>`));
for(const a of published){const dir=path.join('dist/articles',a.slug);fs.mkdirSync(dir,{recursive:true});fs.writeFileSync(path.join(dir,'index.html'),page(a.title,`<a href="/" class="back">← Tous les articles</a><article class="story"><p class="category">${esc(a.category||'Général')}</p><h1>${esc(a.title)}</h1><p class="byline">${esc(a.author||'')}</p>${a.content.split(/\n\s*\n/).map(p=>`<p>${esc(p).replace(/\n/g,'<br>')}</p>`).join('')}</article>`));}
for(const name of ['style.css','search.js'])fs.copyFileSync(name,path.join('dist',name));
console.log(`${published.length} article(s) publié(s) dans dist/.`);

const search=document.querySelector('#search'),category=document.querySelector('#category');
function filter(){let visible=0;for(const card of document.querySelectorAll('[data-search]')){const match=card.dataset.search.includes(search.value.toLowerCase().trim())&&(!category.value||category.value===card.dataset.category);card.hidden=!match;if(match)visible++;}document.querySelector('#empty').hidden=visible>0;}
if(search&&category){search.addEventListener('input',filter);category.addEventListener('change',filter);}
